INSERT INTO `creature_text` (`entry`,`groupid`,`id`,`text`,`type`,`language`,`probability`,`emote`,`duration`,`sound`,`comment`) VALUES
(11747,0,0,'%s becomes enraged!',16,0,100.0,0,0,0,'Desert Rager'),
(12178,0,0,'%s\'s death wail has stirred the nearby silithid hive!',16,0,100.0,0,0,0,'Tortured Druid'),
(12179,0,0,'%s\'s death wail has stirred the nearby silithid hive!',16,0,100.0,0,0,0,'Tortured Sentinel'),
(15181,0,0,'Take this enchanted shard, $n. I will be able to hear the dwarves myself through its twin.',12,0,100.0,0,0,0,''),
(15189,0,0,'You were always the troublemaker in the family, Noggle.  Always!',12,0,100.0,0,0,0,''),
(15190,0,0,'Yes! I\'m cured!  I\'m cure... whoa, got up too fast!',12,0,100.0,0,0,0,''),
(15190,1,0,'Thanks for finding my reagents!  *yawn*  That poison\'s made me... a bit tired...',12,0,100.0,0,0,0,''),
(15215,0,0,'Take this enchanted shard, $n. I will be able to hear the dwarves myself through its twin.',12,0,100.0,0,0,0,''),
(16781,0,0,'The Horde fires will never be extinguished!',12,1,100.0,1,0,0,'Celebrant for the Horde'),
(16781,1,0,'I\'d like to see the Alliance try to steal our flame.',12,1,100.0,1,0,0,'Celebrant - Horde speech'),
(16781,2,0,'The Horde have tried to steal our flames.  I hope we return the favor.',12,7,100.0,1,0,0,'Celebrant - Alliance speech'),
(16781,3,0,'The Alliance fires burn strong and true!',12,7,100.0,1,0,0,'Celebrant - Alliance speech'),
(16781,4,0,'Midsummer Fire Festival is a great time to celebrate the summer!',12,0,100.0,1,0,0,'Celebrant -  speech'),
(16781,5,0,'I love the firework show at the end of Midsummer Firefestival.',12,0,100.0,1,0,0,'Celebrant -  speech'),
(26215,0,0,'You will not stop the Frost Lord from entering this world, mortal. The Tidehunter\'s might will crush that of Ragnaros once and for all, leaving your land a frozen paradise!',12,0,100.0,1,2000,0,'Glacial Lieutenant intro speech'),
(26401,0,0,'Thank you again, $n, for this delectable incense.',12,0,100.0,1,1000,0,'Summer Scorchling'),
(26401,1,0,'%s devours the incense.  It\'s ravenous!',16,0,100.0,1,1000,0,'Summer Scorchling'),
(26401,2,0,'So good! So packed with energy!',12,0,100.0,1,1000,0,'Summer Scorchling'),
(26401,3,0,'It has everything a growing scorchling needs!',12,0,100.0,1,1000,0,'Summer Scorchling'),
(26401,4,0,'I can feel the power SURGING within me!',12,0,100.0,1,1000,0,'Summer Scorchling'),
(26401,5,0,'%s bellows with laughter!',16,0,100.0,1,1000,0,'Summer Scorchling'),
(26401,6,0,'Now! Finally! Our plans can take effect!',12,0,100.0,1,1000,0,'Summer Scorchling'),
(26401,7,0,'KNEEL, LITTLE MORTAL! KNEEL BEFORE THE MIGHT OF THE HERALD OF RAGNAROS!',12,0,100.0,1,1000,0,'Summer Scorchling'),
(26401,8,0,'YOU WILL ALL PERISH IN FLAMES!',12,0,100.0,1,1000,0,'Summer Scorchling'),
(26401,9,0,'%s blinks...',16,0,100.0,1,1000,0,'Summer Scorchling'),
(26401,10,0,'Ah. I was merely jesting...',12,0,100.0,1,1000,0,'Summer Scorchling'),
(26520,0,0,'Thank you again, $n, for this delectable incense.',12,0,100.0,1,1000,0,'Festival Scorchling'),
(26520,1,0,'%s devours the incense.  It\'s ravenous!',16,0,100.0,1,1000,0,'Festival Scorchling'),
(26520,2,0,'So good! So packed with energy!',12,0,100.0,1,1000,0,'Festival Scorchling'),
(26520,3,0,'It has everything a growing scorchling needs!',12,0,100.0,1,1000,0,'Festival Scorchling'),
(26520,4,0,'I can feel the power SURGING within me!',12,0,100.0,1,1000,0,'Festival Scorchling'),
(26520,5,0,'%s bellows with laughter!',16,0,100.0,1,1000,0,'Festival Scorchling'),
(26520,6,0,'Now! Finally! Our plans can take effect!',12,0,100.0,1,1000,0,'Festival Scorchling'),
(26520,7,0,'KNEEL, LITTLE MORTAL! KNEEL BEFORE THE MIGHT OF THE HERALD OF RAGNAROS!',12,0,100.0,1,1000,0,'Festival Scorchling'),
(26520,8,0,'YOU WILL ALL PERISH IN FLAMES!',12,0,100.0,1,1000,0,'Festival Scorchling'),
(26520,9,0,'%s blinks...',16,0,100.0,1,1000,0,'Festival Scorchling'),
(26520,10,0,'Ah. I was merely jesting...',12,0,100.0,1,1000,0,'Festival Scorchling'),
(27588,0,0,'Without you we\'d be lost. Thanks for the ride!',12,7,100.0,0,0,0,'7th Legion Elite'),
(27588,0,1,'For the Alliance and Lord Fordragon!',12,7,100.0,0,0,0,'7th Legion Elite'),
(27588,0,2,'HOO-WAH! The cavalry has arrived!',12,7,100.0,0,0,0,'7th Legion Elite'),
(27588,0,3,'Great driving, soldier! Not a scratch on us!',12,7,100.0,0,0,0,'7th Legion Elite'),
(27588,1,0,'I think I see one of their plague wagons!',12,0,100.0,0,0,0,'7th Legion Elite'),
(27588,1,1,'Did I ever tell you soldiers about the time I destroyed the Thandol Span? Yep, weren\'t no dark irons destroyed that bridge! Was me!',12,7,100.0,0,0,0,'7th Legion Elite'),
(27588,1,2,'It doesn\'t make any sense. Why don\'t they just fly Naxxramas over Wintergarde Keep and blow it up? I mean, that\'s what I would do if I were Kel\'Thuzad.',12,7,100.0,0,0,0,'7th Legion Elite'),
(27588,1,3,'I wonder if we\'ll ever solve the mystery of the strange ore. There\'s gotta be some use for it!',12,0,100.0,0,0,0,'7th Legion Elite'),
(27588,1,4,'Hey, do any of you know McGoyver over at Valgarde? He\'s my uncle. You know what his title is? Pro. Yea, just \"Pro.\" I want to be a pro too.',12,0,100.0,0,0,0,'7th Legion Elite'),
(27588,1,5,'Something straight up stinks in here! It\'s definitely not me. Gnomes smell like butter and sunshine. Not like those dwarves that smell like they were born from a trogg\'s armpit! None of you are dwarves, are you?',12,0,100.0,0,0,0,'7th Legion Elite'),
(27588,1,6,'I used to know a dwarf that claimed gnomes evolved from beneath the earth. That we all started out as sand gnomes. What a load of nonsense! Sand gnomes? PUH-LEASE!',12,0,100.0,0,0,0,'7th Legion Elite'),
(27588,1,7,'I\'ve never seen destruction like this...',12,0,100.0,0,0,0,'7th Legion Elite'),
(27588,1,8,'Keep the chatter down, people. We need to stay alert!',12,0,100.0,0,0,0,'7th Legion Elite'),
(27588,1,9,'The smell of death covers every inch of this place.',12,0,100.0,0,0,0,'7th Legion Elite'),
(27588,1,10,'Driver, I hear you single handedly airlifted our villagers out of this hell-hole. Is that true?',12,0,100.0,0,0,0,'7th Legion Elite'),
(27588,1,11,'So does anyone know anything about Thel\'zan? Who is he? How did he come to leading the Scourge armies on the ground?',12,0,100.0,0,0,0,'7th Legion Elite'),
(27588,1,12,'Look at this mess... The Scourge will pay for this!',12,0,100.0,0,0,0,'7th Legion Elite'),
(27588,1,13,'Where are all the corpses? What have they done to our people?',12,0,100.0,0,0,0,'7th Legion Elite'),
(27588,1,14,'I hope I\'m alive to see Arthas get what\'s coming to him.',12,0,100.0,0,0,0,'7th Legion Elite'),
(27588,2,0,'Reporting for duty, sir!',12,7,100.0,0,0,0,'7th Legion Elite');
